    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(clock), LocalDate.now(clock)));
            } catch (DataIntegrityViolationException e) {
                // Another user started the same sheet at the same moment.
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /** The sheet's today: the date every date-dependent decision and default on it uses. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseThrow(SheetNotFoundException::new);
    }

    /** Whether a claim opened now on the sheet is numbered within its period (see {@link Sheet#numbersByPeriod()}). */
    @Transactional(readOnly = true)
    public boolean numbersByPeriod(String id) {
        return sheets.findById(id).map(Sheet::numbersByPeriod).orElseThrow(SheetNotFoundException::new);
    }

    /** Change the sheet's today; the figures it moves are recorded as {@code user}'s change. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = sheets.findById(id).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        rollup.recordSince(id, user, before);
        return sheet;
    }

    /** The next claim number on the sheet: 1 for its first, then 2, and so on, never given twice. */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.advanceClaimNumber(id) == 0) throw new SheetNotFoundException();
        return sheets.lastClaimNumber(id);
    }

    /** The next number in the sheet's sequence named {@code key}: 1 for its first, then 2, and so on,
     * never given twice. */
    @Transactional
    public int nextInSequence(String id, String key) {
        if (sheets.lockSheet(id) == 0) throw new SheetNotFoundException();
        if (sheets.advanceSequence(id, key) == 0) sheets.startSequence(id, key);
        return sheets.lastInSequence(id, key);
    }
}
-- A sheet's settings that carry a figure, each recorded from a date: the floor, the late percent, the
-- terms (the sheet's, and each grade's as terms-<grade>), the clerk limit and the cap. The value in
-- force on a date is the one with the latest from-date on or before it; before every from-date it is
-- the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none for the others). A null
-- value records "none" from that date: no clerk limit, no cap, or a grade using the sheet's terms.
CREATE TABLE sheet_setting (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(20)
);
CREATE UNIQUE INDEX sheet_setting_sheet_key_from ON sheet_setting (sheet_id, setting_key, from_date);

-- The values already kept are in force from the beginning of time.
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;

DROP TABLE sheet_grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
-- The role each user name has on a sheet: CLERK or STEWARD. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('CLERK', 'STEWARD'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);

-- The most a clerk may settle a claim for: its due must be at or below it. Null means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(12, 2) CHECK (clerk_limit >= 0);

package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it (a clerk unless made a steward) and its clerk
 * limit, the most a clerk may settle a claim for (none when null), and its floor, the least a claim's
 * live due can be, and its cap, the most a person's due-total can be (none when null), and its terms, how many days after its date a claim is due by (each grade may have its own
 * terms in their place), and its late percent, the
 * percent of its figure an overdue claim's due gains for every full 30 days it is overdue, and its policy
 * date, which decides how a claim's live figures round (the sheet's today when none is set), and its
 * period numbering from, the date from which a claim opened is numbered within its period (off when null),
 * and its proof threshold, above which a claim's due needs a proof before it is settled (none when null).
 * The settings that carry a figure (the clerk limit, the floor, the cap, the terms, the late percent and the proof threshold)
 * are dated: each value is recorded from a date (see {@link DatedSettings}); the policy date and the
 * period numbering from are not. */
@Service
public class SettingsService {

    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final SheetRoleRepository roles;
    private final SheetSettingRepository settings;
    private final DatedSettings dated;
    private final RollupService rollup;
    private final Audit audit;

    public SettingsService(SheetRepository sheets, SheetRoleRepository roles, SheetSettingRepository settings,
            DatedSettings dated, RollupService rollup, Audit audit) {
        this.sheets = sheets;
        this.roles = roles;
        this.settings = settings;
        this.dated = dated;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles given on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUser(sheetId);
    }

    /** The user's role on the sheet: a clerk unless made something else. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
        SheetRole given = roles.findBySheetIdAndUser(sheetId, user).orElse(null);
        if (given == null) {
            given = roles.saveAndFlush(new SheetRole(sheetId, user, role));
        } else {
            given.setRole(role);
            roles.flush();
        }
        audit.change("ROLE_SET", sheetId, by, "user=" + user, "role=" + role.name().toLowerCase());
        return given;
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return dated.clerkLimit(sheetId);
    }

    /** Record the sheet's clerk limit from {@code from} (the sheet's today when null); null records no limit. */
    @Transactional
    public void setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
        record(sheetId, by, DatedSettings.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /** The floor in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return dated.floorOn(sheetId, today(sheetId));
    }

    /** Record the sheet's floor from {@code from} (the sheet's today when null); the live dues of the
     * claims dated from then, and so the figures, follow it. */
    @Transactional
    public void setFloor(String sheetId, String by, BigDecimal floor, LocalDate from) {
        record(sheetId, by, DatedSettings.FLOOR, floor.toPlainString(), from, true);
    }

    /** The cap in force on the sheet's today, the most a person's due-total can be; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String sheetId) {
        return dated.cap(sheetId);
    }

    /** Record the sheet's cap from {@code from} (the sheet's today when null); null records no cap. The
     * due-totals, and so the figures, follow the cap in force on the sheet's today. */
    @Transactional
    public void setCap(String sheetId, String by, BigDecimal cap, LocalDate from) {
        record(sheetId, by, DatedSettings.CAP, cap == null ? null : cap.toPlainString(), from, true);
    }

    /** The sheet's terms in force on its today, in days. */
    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return dated.termsOn(sheetId, today(sheetId));
    }

    /** Record the sheet's terms from {@code from} (the sheet's today when null); only the claims added
     * from then on, dated on or after it, of a person whose grade has no terms of its own then, are due
     * by them. */
    @Transactional
    public void setTerms(String sheetId, String by, int terms, LocalDate from) {
        record(sheetId, by, DatedSettings.TERMS, String.valueOf(terms), from, false);
    }

    /** The grades with their own terms in force on the sheet's today, by grade, in days. */
    @Transactional(readOnly = true)
    public Map<String, Integer> gradeTerms(String sheetId) {
        LocalDate today = today(sheetId);
        Map<String, Integer> terms = new LinkedHashMap<>();
        for (String grade : GRADES) {
            Integer own = dated.gradeTermsOn(sheetId, grade, today);
            if (own != null) terms.put(grade, own);
        }
        return terms;
    }

    /** The terms a claim dated {@code date} of a person of {@code grade} is due by (see {@link DatedSettings#termsFor}). */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return dated.termsFor(sheetId, grade, date);
    }

    /** Record the grade's own terms from {@code from} (the sheet's today when null); null records that
     * the grade uses the sheet's terms from then. Only the claims added from then on are due by them. */
    @Transactional
    public void setGradeTerms(String sheetId, String by, String grade, Integer terms, LocalDate from) {
        record(sheetId, by, DatedSettings.gradeTermsKey(grade), terms == null ? null : String.valueOf(terms), from,
                false);
    }

    /** The late percent in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String sheetId) {
        return dated.latePctOn(sheetId, today(sheetId));
    }

    /** Record the sheet's late percent from {@code from} (the sheet's today when null); the late charges
     * of the claims dated from then, and so the figures, follow it. */
    @Transactional
    public void setLatePct(String sheetId, String by, BigDecimal latePct, LocalDate from) {
        record(sheetId, by, DatedSettings.LATE_PCT, latePct.toPlainString(), from, true);
    }

    /** The proof threshold in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThreshold(String sheetId) {
        return dated.proofThresholdOn(sheetId, today(sheetId));
    }

    /** The proof threshold in force on {@code date}: a claim dated then whose due is above it cannot be
     * settled or approved while it has no proofs; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdOn(String sheetId, LocalDate date) {
        return dated.proofThresholdOn(sheetId, date);
    }

    /** Record the sheet's proof threshold from {@code from} (the sheet's today when null); null records
     * no threshold. */
    @Transactional
    public void setProofThreshold(String sheetId, String by, BigDecimal threshold, LocalDate from) {
        record(sheetId, by, DatedSettings.PROOF_THRESHOLD, threshold == null ? null : threshold.toPlainString(), from, false);
    }

    /** Every value recorded for the dated setting {@code key}, oldest from-date first. */
    @Transactional(readOnly = true)
    public List<SheetSetting> history(String sheetId, String key) {
        return dated.history(sheetId, key);
    }

    /** Record {@code value} for the dated setting {@code key} from {@code from} (the sheet's today when
     * null), keeping the values already recorded; one already recorded from that date is replaced. The
     * SETTING_CHANGED line ends with the from-date when one was given; when {@code figures} the ROLLUP
     * and TOTALS lines follow it. */
    private void record(String sheetId, String by, String key, String value, LocalDate from, boolean figures) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = figures ? rollup.snapshot(sheetId) : null;
        LocalDate on = from == null ? sheet.getToday() : from;
        SheetSetting recorded = settings.findBySheetIdAndKeyAndFrom(sheetId, key, on).orElse(null);
        if (recorded == null) {
            settings.save(new SheetSetting(sheetId, key, on, value));
        } else {
            recorded.setValue(value);
        }
        settings.flush();
        List<String> fields = new ArrayList<>(List.of("key=" + key, "value=" + (value == null ? "" : value)));
        if (from != null) fields.add("from=" + from);
        audit.change("SETTING_CHANGED", sheetId, by, fields.toArray(String[]::new));
        if (figures) rollup.recordSince(sheetId, by, before);
    }

    private LocalDate today(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
    }

    /** The sheet's policy date as set; null when it is the sheet's today. */
    @Transactional(readOnly = true)
    public LocalDate policyDate(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getPolicyDate();
    }

    /** Set the sheet's policy date; null makes it the sheet's today. The live figures' rounding follows it. */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String by, LocalDate policyDate) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        sheets.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=policy-date",
                "value=" + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordSince(sheetId, by, before);
        return sheet;
    }

    /** The sheet's period numbering from; null when it is off. */
    @Transactional(readOnly = true)
    public LocalDate periodNumberingFrom(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getPeriodNumberingFrom();
    }

    /** Set the sheet's period numbering from; null turns it off. Only the claims opened from then on follow it. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String by, LocalDate from) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setPeriodNumberingFrom(from);
        sheets.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=period-numbering-from",
                "value=" + (from == null ? "" : from.toString()));
        return sheet;
    }
}
package net.officefloor.hq.app.settings;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** A sheet's settings: its roles, its clerk limit, its floor, its cap, its terms, its late percent (each dated: saved with a from-date, the sheet's today when blank), its policy date and its period numbering from. The signed-in user's name travels in the
 * {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class SettingsController {

    /** A user name and the role it has on the sheet (clerk or steward). */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUser(), role.getRole().name().toLowerCase());
        }
    }

    /** The sheet's settings; the floor is sent as text with two decimals; the cap is sent as text with two decimals, null when there is none; the clerk limit is sent as text with two decimals, null when there is none; the terms in days; the grades' own terms in days, by grade (a grade not in it uses the sheet's terms); the late percent as text with two decimals; the policy date as set, null when it is the sheet's today; the period numbering from, null when it is off. The clerk limit, the floor, the cap, the terms, the grades' own terms and the late percent are those in force on the sheet's today; every floor, late percent and cap recorded, each from its date, oldest first, follow (a claim's floor and late percent are those in force on its date; a cap recorded as none is null); the proof threshold in force on the sheet's today, as text with two decimals, null when there is none, follows. */
    public record SettingsView(String clerkLimit, String floor, String cap, int terms, Map<String, Integer> gradeTerms, String latePct, LocalDate policyDate,
            List<RoleView> roles, LocalDate periodNumberingFrom, List<DatedView> floors, List<DatedView> latePcts, List<DatedView> caps,
            String proofThreshold) {
    }

    /** A value of a dated setting, as text, and the date it is recorded from. */
    public record DatedView(LocalDate from, String value) {
        static DatedView of(SheetSetting setting) {
            return new DatedView(setting.getFrom(), setting.getValue());
        }
    }

    /** A role: clerk or steward. */
    public record RoleRequest(@NotNull @Pattern(regexp = "\\s*(clerk|steward)\\s*") String role) {
        Role roleValue() {
            return Role.valueOf(role.trim().toUpperCase());
        }
    }

    /** A clerk limit: 0.00 or more, with up to two decimals; blank or null for no limit. */
    public record ClerkLimitRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal limitValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A floor: 0.00 or more, with up to two decimals. */
    public record FloorRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal floorValue() {
            return new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A cap: 0.00 or more, with up to two decimals; blank or null for no cap. */
    public record CapRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal capValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A proof threshold: 0.00 or more, with up to two decimals; blank or null for none. */
    public record ProofThresholdRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal thresholdValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** Terms: a whole number of days, 0 or more. */
    public record TermsRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,4}\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        int termsValue() {
            return Integer.parseInt(value.trim());
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A grade's own terms: a whole number of days, 0 or more; blank or null to use the sheet's terms. */
    public record GradeTermsRequest(@Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        Integer termsValue() {
            return value == null || value.isBlank() ? null : Integer.parseInt(value.trim());
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A late percent: 0.00 or more, with up to two decimals. */
    public record LatePctRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal latePctValue() {
            return new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A from-date (YYYY-MM-DD); null when blank or null, for the sheet's today. */
    private static LocalDate fromOf(String from) {
        return from == null || from.isBlank() ? null : LocalDate.parse(from.trim());
    }

    /** A policy date (YYYY-MM-DD); blank or null for the sheet's today. */
    public record PolicyDateRequest(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {
        LocalDate dateValue() {
            return value == null || value.isBlank() ? null : LocalDate.parse(value.trim());
        }
    }

    /** A period numbering from date (YYYY-MM-DD); blank or null turns it off. */
    public record PeriodNumberingFromRequest(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {
        LocalDate dateValue() {
            return value == null || value.isBlank() ? null : LocalDate.parse(value.trim());
        }
    }

    private final SettingsService service;

    public SettingsController(SettingsService service) {
        this.service = service;
    }

    @GetMapping("/settings")
    public SettingsView get(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        String sheet = sheetId.trim();
        return new SettingsView(text(service.clerkLimit(sheet)), text(service.floor(sheet)),
                text(service.cap(sheet)), service.terms(sheet),
                service.gradeTerms(sheet),
                text(service.latePct(sheet)), service.policyDate(sheet), service.roles(sheet).stream().map(RoleView::of).toList(),
                service.periodNumberingFrom(sheet),
                service.history(sheet, DatedSettings.FLOOR).stream().map(DatedView::of).toList(),
                service.history(sheet, DatedSettings.LATE_PCT).stream().map(DatedView::of).toList(),
                service.history(sheet, DatedSettings.CAP).stream().map(DatedView::of).toList(),
                text(service.proofThreshold(sheet)));
    }

    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClerkLimitRequest request) {
        String sheet = sheetId.trim();
        service.setClerkLimit(sheet, user.trim(), request.limitValue(), request.fromValue());
        return get(sheet, user);
    }

    @PutMapping("/settings/cap")
    public SettingsView setCap(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid CapRequest request) {
        String sheet = sheetId.trim();
        service.setCap(sheet, user.trim(), request.capValue(), request.fromValue());
        return get(sheet, user);
    }

    @PutMapping("/settings/proof-threshold")
    public SettingsView setProofThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ProofThresholdRequest request) {
        String sheet = sheetId.trim();
