407	    // What is in force follows the sheet's today: re-read it when the today changes.
408	    let shownToday: string | null = null;
409	    effect(() => {
410	      const today = this.session.today();
411	      const sheet = untracked(() => this.session.sheetId());
412	      if (shownToday !== null && today !== shownToday && sheet) void this.read(sheet);
413	      shownToday = today;
414	    });
415	  }
416	
417	  protected value(event: Event): string {
418	    return (event.target as HTMLInputElement).value;
419	  }
420	
421	  protected setGradeTermsFrom(grade: Grade, text: string): void {
422	    this.gradeTermsFrom.update((inputs) => ({ ...inputs, [grade]: text }));
423	  }
424	
425	  protected setGradeTermsInput(grade: Grade, text: string): void {
426	    this.gradeTermsInput.update((inputs) => ({ ...inputs, [grade]: text }));
427	  }
428	
429	  /** The grade's own terms in force, as text; empty when it uses the sheet's terms. */
430	  protected gradeTermsShown(grade: Grade): string {
431	    const own = this.gradeTerms()[grade];
432	    return own === undefined ? '' : String(own);
433	  }
434	
435	  protected async saveSettings(event: Event): Promise<void> {
436	    event.preventDefault();
437	    if (this.savingSettings) {
438	      this.settingsResubmit = true;
439	      return;
440	    }
441	    this.settingsError.set(null);
442	    const sheet = this.session.sheetId();
443	    if (!sheet) return;
444	    const limit = this.limit().trim();
445	    const floor = this.floorInput().trim();
446	    const saveLimit = this.limitChanged || limit !== (this.clerkLimit() ?? '');
447	    const saveFloor = this.floorChanged || floor !== this.floor();
448	    const cap = this.capInput().trim();
449	    const saveCap = this.capChanged || cap !== (this.cap() ?? '');
450	    const proofThreshold = this.proofThresholdInput().trim();
451	    const saveProofThreshold = this.proofThresholdChanged || proofThreshold !== (this.proofThreshold() ?? '');
452	    const terms = this.termsInput().trim();
453	    const saveTerms = this.termsChanged || terms !== this.terms();
454	    const gradeTerms = GRADES.map((grade) => ({ grade, text: this.gradeTermsInput()[grade].trim() })).filter(
455	      ({ grade, text }) => this.gradeTermsChanged.has(grade) || text !== this.gradeTermsShown(grade),
456	    );
457	    const latePct = this.latePctInput().trim();
458	    const saveLatePct = this.latePctChanged || latePct !== this.latePct();
459	    const policyDate = this.policyDateInput().trim();
460	    const savePolicyDate = this.policyDateChanged || policyDate !== (this.policyDate() ?? '');
461	    const numberingFrom = this.periodNumberingFromInput().trim();
462	    const saveNumberingFrom =
463	      this.periodNumberingFromChanged || numberingFrom !== (this.periodNumberingFrom() ?? '');
464	    const limitFrom = this.limitFrom().trim();
465	    const floorFrom = this.floorFrom().trim();
466	    const capFrom = this.capFrom().trim();
467	    const proofThresholdFrom = this.proofThresholdFrom().trim();
468	    const termsFrom = this.termsFrom().trim();
469	    const latePctFrom = this.latePctFrom().trim();
470	    const gradeTermsFrom = { ...this.gradeTermsFrom() };
471	    const badFrom = [
472	      saveLimit ? limitFrom : '',
473	      saveFloor ? floorFrom : '',
474	      saveCap ? capFrom : '',
475	      saveProofThreshold ? proofThresholdFrom : '',
476	      saveTerms ? termsFrom : '',
477	      saveLatePct ? latePctFrom : '',
478	      ...gradeTerms.map(({ grade }) => gradeTermsFrom[grade].trim()),
479	    ].some((from) => from !== '' && !DATE.test(from));
480	    if (badFrom) {
481	      this.settingsError.set('Type a from-date as YYYY-MM-DD, or leave it blank for the sheet\'s today.');
482	      return;
483	    }
484	    if (saveLimit && limit !== '' && !LIMIT.test(limit)) {
485	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
486	      return;
487	    }
488	    if (saveFloor && !LIMIT.test(floor)) {
489	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
490	      return;
491	    }
492	    if (saveCap && cap !== '' && !LIMIT.test(cap)) {
493	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank.');
494	      return;
495	    }
496	    if (saveProofThreshold && proofThreshold !== '' && !LIMIT.test(proofThreshold)) {
497	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it blank.');
498	      return;
499	    }
500	    if (saveTerms && !TERMS.test(terms)) {
501	      this.settingsError.set('Type terms as a whole number of days, 0 or more.');
502	      return;
503	    }
504	    const badGrade = gradeTerms.find(({ text }) => text !== '' && !TERMS.test(text));
505	    if (badGrade) {
506	      this.settingsError.set(
507	        `Type terms for grade ${badGrade.grade} as a whole number of days, 0 or more, or leave them blank for the sheet's terms.`,
508	      );
509	      return;
510	    }
511	    if (saveLatePct && !LIMIT.test(latePct)) {
512	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
513	      return;
514	    }
515	    if (savePolicyDate && policyDate !== '' && !DATE.test(policyDate)) {
516	      this.settingsError.set('Type a policy date as YYYY-MM-DD, or leave it blank for the sheet\'s today.');
517	      return;
518	    }
519	    if (saveNumberingFrom && numberingFrom !== '' && !DATE.test(numberingFrom)) {
520	      this.settingsError.set('Type a period numbering from date as YYYY-MM-DD, or leave it blank to turn it off.');
521	      return;
522	    }
523	    this.savingSettings = true;
524	    try {
525	      if (saveLimit) {
526	        const settings = await this.service.setClerkLimit(sheet, limit || null, limitFrom || null);
527	        if (this.session.sheetId() !== sheet) return;
528	        if (this.limit().trim() === limit && this.limitFrom().trim() === limitFrom) {
529	          this.limitChanged = false;
530	          this.limitFrom.set('');
531	        }
532	        this.show(settings);
533	      }
534	      if (saveFloor) {
535	        const settings = await this.service.setFloor(sheet, floor, floorFrom || null);
536	        if (this.session.sheetId() !== sheet) return;
537	        if (this.floorInput().trim() === floor && this.floorFrom().trim() === floorFrom) {
538	          this.floorChanged = false;
539	          this.floorFrom.set('');
540	        }
541	        this.show(settings);
542	        this.floorSaved.emit(settings.floors);
543	      }
544	      if (saveCap) {
545	        const settings = await this.service.setCap(sheet, cap || null, capFrom || null);
546	        if (this.session.sheetId() !== sheet) return;
547	        if (this.capInput().trim() === cap && this.capFrom().trim() === capFrom) {
548	          this.capChanged = false;
549	          this.capFrom.set('');
550	        }
551	        this.show(settings);
552	        this.capSaved.emit(settings.caps);
553	      }
554	      if (saveProofThreshold) {
555	        const settings = await this.service.setProofThreshold(sheet, proofThreshold || null, proofThresholdFrom || null);
556	        if (this.session.sheetId() !== sheet) return;
557	        if (this.proofThresholdInput().trim() === proofThreshold && this.proofThresholdFrom().trim() === proofThresholdFrom) {
558	          this.proofThresholdChanged = false;
559	          this.proofThresholdFrom.set('');
560	        }
561	        this.show(settings);
562	      }
563	      if (saveTerms) {
564	        const settings = await this.service.setTerms(sheet, terms, termsFrom || null);
565	        if (this.session.sheetId() !== sheet) return;
566	        if (this.termsInput().trim() === terms && this.termsFrom().trim() === termsFrom) {
567	          this.termsChanged = false;
568	          this.termsFrom.set('');
569	        }
570	        this.show(settings);
571	      }
572	      for (const { grade, text } of gradeTerms) {
573	        const from = gradeTermsFrom[grade].trim();
574	        const settings = await this.service.setGradeTerms(sheet, grade, text || null, from || null);
575	        if (this.session.sheetId() !== sheet) return;
576	        if (this.gradeTermsInput()[grade].trim() === text && this.gradeTermsFrom()[grade].trim() === from) {
577	          this.gradeTermsChanged.delete(grade);
578	          this.setGradeTermsFrom(grade, '');
579	        }
580	        this.show(settings);
581	      }
582	      if (saveLatePct) {
583	        const settings = await this.service.setLatePct(sheet, latePct, latePctFrom || null);
584	        if (this.session.sheetId() !== sheet) return;
585	        if (this.latePctInput().trim() === latePct && this.latePctFrom().trim() === latePctFrom) {
586	          this.latePctChanged = false;
587	          this.latePctFrom.set('');
588	        }
589	        this.show(settings);
590	        this.latePctSaved.emit(settings.latePcts);
591	      }
592	      if (savePolicyDate) {
593	        const settings = await this.service.setPolicyDate(sheet, policyDate || null);
594	        if (this.session.sheetId() !== sheet) return;
595	        if (this.policyDateInput().trim() === policyDate) this.policyDateChanged = false;
596	        this.show(settings);
597	        this.policyDateSaved.emit(settings.policyDate);
598	      }
599	      if (saveNumberingFrom) {
600	        const settings = await this.service.setPeriodNumberingFrom(sheet, numberingFrom || null);
601	        if (this.session.sheetId() !== sheet) return;
602	        if (this.periodNumberingFromInput().trim() === numberingFrom) this.periodNumberingFromChanged = false;
603	        this.show(settings);
604	      }
605	      // Show what is in force in each field, but keep what was typed in one while the save was waiting.
606	      if (!this.limitChanged) this.limit.set(this.clerkLimit() ?? '');
607	      if (!this.floorChanged) this.floorInput.set(this.floor());
608	      if (!this.capChanged) this.capInput.set(this.cap() ?? '');
609	      if (!this.proofThresholdChanged) this.proofThresholdInput.set(this.proofThreshold() ?? '');
610	      if (!this.termsChanged) this.termsInput.set(this.terms());
611	      if (!this.latePctChanged) this.latePctInput.set(this.latePct());
612	      this.showGradeTermsInputs();
613	      if (!this.policyDateChanged) this.policyDateInput.set(this.policyDate() ?? '');
614	      if (!this.periodNumberingFromChanged) this.periodNumberingFromInput.set(this.periodNumberingFrom() ?? '');
615	    } catch {
616	      this.settingsError.set('Those settings could not be saved.');
617	    } finally {
618	      this.savingSettings = false;
619	      if (this.settingsResubmit) {
620	        this.settingsResubmit = false;
621	        void this.saveSettings(event);
622	      }
623	    }
624	  }
625	
626	  protected async saveRole(event: Event): Promise<void> {
627	    event.preventDefault();
628	    if (this.savingRole) return;
629	    this.roleError.set(null);
630	    const sheet = this.session.sheetId();
631	    if (!sheet) return;
632	    const user = this.roleUser().trim();
633	    const role = this.role().trim();
634	    if (user === '') {
635	      this.roleError.set('Type a user name.');
636	      return;
637	    }
638	    if (!ROLES.includes(role as Role)) {
639	      this.roleError.set(`Choose a role: ${ROLES.join(' or ')}.`);
640	      return;
641	    }
642	    this.savingRole = true;
643	    try {
644	      const saved = await this.service.setRole(sheet, user, role as Role);
645	      if (this.session.sheetId() !== sheet) return;
646	      this.given.update((list) =>
647	        [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
648	      );
649	      this.roleUser.set('');
650	      this.role.set('');
651	    } catch {
652	      this.roleError.set('That role could not be set.');
653	    } finally {
654	      this.savingRole = false;
655	    }
656	  }
657	
658	  private async read(sheet: string): Promise<void> {
659	    try {
660	      const settings = await this.service.get(sheet);
661	      if (this.session.sheetId() === sheet) {
662	        this.show(settings);
663	        if (!this.limitChanged) this.limit.set(settings.clerkLimit ?? '');
664	        if (!this.floorChanged) this.floorInput.set(settings.floor);
665	        if (!this.capChanged) this.capInput.set(settings.cap ?? '');
666	        if (!this.proofThresholdChanged) this.proofThresholdInput.set(settings.proofThreshold ?? '');
667	        if (!this.termsChanged) this.termsInput.set(String(settings.terms));
668	        if (!this.latePctChanged) this.latePctInput.set(settings.latePct);
669	        this.showGradeTermsInputs();
670	        if (!this.policyDateChanged) this.policyDateInput.set(settings.policyDate ?? '');
671	        if (!this.periodNumberingFromChanged) this.periodNumberingFromInput.set(settings.periodNumberingFrom ?? '');
672	      }
673	    } catch {
674	      // The settings could not be read; they show as none.
675	    }
676	  }
677	
678	  /** Show each grade's own terms in force in its field, but keep what was typed in one since. */
679	  private showGradeTermsInputs(): void {
680	    this.gradeTermsInput.update((inputs) => {
681	      const next = { ...inputs };
682	      for (const grade of GRADES) if (!this.gradeTermsChanged.has(grade)) next[grade] = this.gradeTermsShown(grade);
683	      return next;
684	    });
685	  }
686	
687	  private show(settings: SheetSettings): void {
688	    this.clerkLimit.set(settings.clerkLimit);
689	    this.floor.set(settings.floor);
690	    this.cap.set(settings.cap);
691	    this.proofThreshold.set(settings.proofThreshold);
692	    this.terms.set(String(settings.terms));
693	    this.gradeTerms.set(settings.gradeTerms ?? {});
694	    this.latePct.set(settings.latePct);
695	    this.policyDate.set(settings.policyDate);
696	    this.periodNumberingFrom.set(settings.periodNumberingFrom);
697	    this.given.set(settings.roles);
698	  }
699	}
700	
701	function blankGrades(): Record<Grade, string> {
702	  return { A: '', B: '', C: '' };
703	}
